import 'package:flutter/material.dart';
class GenerateSubjectScreen extends StatefulWidget{const GenerateSubjectScreen({super.key}); @override State<GenerateSubjectScreen> createState()=>_GenerateSubjectScreenState();}
class _GenerateSubjectScreenState extends State<GenerateSubjectScreen>{String classe='2nde',discipline='Physique',chapter='Mécanique'; bool loading=false; String? result;
 @override Widget build(BuildContext c)=>Scaffold(backgroundColor const Color(0xff263238),appBar:AppBar(title:const Text('Générateur de sujets APC'),backgroundColor:const Color(0xff37474f)),body:ListView(padding:const EdgeInsets.all(20),children:[_select('Classe',classe,['2nde','1ere C/D','Tle C/D'],(v)=>setState(()=>classe=v!)),_select('Discipline',discipline,['Physique','Chimie'],(v)=>setState(()=>discipline=v!)),_select('Chapitre',chapter,['Mécanique','Électricité','Chimie organique','Solutions aqueuses'],(v)=>setState(()=>chapter=v!)),const SizedBox(height:16),SizedBox(height:52,child:ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:const Color(0xff4caf50),shape:const RoundedRectangleBorder()),onPressed:loading?null:()=>setState((){loading=true;result='Préparation du sujet APC…';}),child:loading?const CircularProgressIndicator():const Text('GÉNÉRER LE SUJET'))),if(result!=null)Card(color:const Color(0xff37474f),shape:const RoundedRectangleBorder(),child:Padding(padding:const EdgeInsets.all(16),child:Text(result!,style:const TextStyle(color:Colors.white))))]));
 Widget _select(String label,String value,List<String> values,ValueChanged<String?> onChanged)=>DropdownButtonFormField<String>(value:value,decoration:InputDecoration(labelText:label,labelStyle:const TextStyle(color:Colors.white)),dropdownColor:const Color(0xff37474f),style:const TextStyle(color:Colors.white),items:values.map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:onChanged);
}
